#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD = 998244353;
constexpr int N = 5000;

array<vector<int>, N + 1> factor;
vector<long long> primes;

long long comb(int m, int n) {
    long long res = 1;
    vector<int> fnm = factor[n];

    for (size_t i = 0; i < factor[m].size(); ++i) {
        fnm[i] += factor[m][i];
    }

    for (int w = 1; w <= m; ++w) {
        long long r = 1;

        for (size_t i = 0; i < primes.size(); ++i) {
            long long p = primes[i];
            int pw = fnm[i] - factor[w][i] - factor[n - w][i]
                     - factor[m - w][i];

            while (pw > 0) {
                if (pw & 1) {
                    r = r * p % MOD;
                }
                p = p * p % MOD;
                pw >>= 1;
            }
        }

        res += r;
    }

    return res % MOD;
}

int main() {
    array<int, 3> abc{};
    cin >> abc[0] >> abc[1] >> abc[2];
    sort(abc.begin(), abc.end());

    array<bool, N + 1> sieve{};
    sieve[0] = sieve[1] = true;

    for (int p = 0; p <= N; ++p) {
        if (!sieve[p]) {
            primes.push_back(p);
            for (int q = p * p; q <= N; q += p) {
                sieve[q] = true;
            }
        }
    }

    for (auto& f : factor) {
        f.assign(primes.size(), 0);
    }

    for (size_t i = 0; i < primes.size(); ++i) {
        long long p = primes[i];

        for (long long pp = p; pp <= N; pp *= p) {
            for (long long j = pp; j <= N; j += pp) {
                ++factor[j][i];
            }
        }
    }

    vector<int>* a = &factor[0];
    for (auto& b : factor) {
        for (size_t i = 0; i < a->size(); ++i) {
            b[i] += (*a)[i];
        }
        a = &b;
    }

    cout << comb(abc[0], abc[1])
                * comb(abc[0], abc[2]) % MOD
                * comb(abc[1], abc[2]) % MOD
         << '\n';

    return 0;
}

